/// Wonky Write's localizations (suite 11 §4): ARB files in this folder,
/// generated by `flutter gen-l10n` (`l10n.yaml`) into `gen/`.
///
/// Widgets use [writeL10n]; code without a `BuildContext` (controllers,
/// commands, toasts) uses [writeL10nOf] with the shell services.
library;

import 'package:flutter/widgets.dart';
import 'package:wonky_app/wonky_app.dart';

import 'gen/write_localizations.dart';

export 'gen/write_localizations.dart';

/// A localized string, resolved when shown (command titles, categories,
/// descriptions).
typedef WriteText = String Function(WriteLocalizations l);

/// The Write strings for [context]. Falls back to English when the app's
/// delegate is not installed (headless contexts, widget tests that pump a
/// bare `ShadApp`).
WriteLocalizations writeL10n(BuildContext context) =>
    Localizations.of<WriteLocalizations>(context, WriteLocalizations) ??
    writeL10nEnglish;

/// The Write strings in the shell's current locale, for code that has no
/// `BuildContext` (controllers, command runs, toasts).
WriteLocalizations writeL10nOf(ShellServices services) {
  final c = services.navigatorContext;
  return c == null ? writeL10nEnglish : writeL10n(c);
}

/// The Write strings matching the shell's [l] (same locale).
WriteLocalizations writeL10nFor(WonkyAppLocalizations l) =>
    writeL10nForLocale(_parseLocale(l.localeName));

/// The Write strings for [locale], English when it is not supported.
WriteLocalizations writeL10nForLocale(Locale locale) {
  final supported = WriteLocalizations.supportedLocales.any(
    (s) =>
        s.languageCode == locale.languageCode &&
        (s.countryCode == null || s.countryCode == locale.countryCode),
  );
  if (!supported) return writeL10nEnglish;
  try {
    return lookupWriteLocalizations(locale);
  } on FlutterError {
    return writeL10nEnglish;
  }
}

/// English strings (the template locale).
final WriteLocalizations writeL10nEnglish = lookupWriteLocalizations(
  const Locale('en'),
);

Locale _parseLocale(String name) {
  final parts = name.split(RegExp('[_-]'));
  return parts.length > 1
      ? Locale(parts[0], parts[1])
      : Locale(parts.isEmpty ? 'en' : parts[0]);
}
